            pk = "|".join(jids)
            if not all(j in ind_asr[ck] for j in jids):
                continue
            if not all(j in clean[ds] and j in attacked[ds].get(atk, {}) for j in jids):
                continue

            asr = compute_panel_asr(jids, clean[ds], attacked[ds][atk], pairs_list[ds])
            keff = keff_cache[ds][pk]
            eta_max = max(ind_asr[ck][j] for j in jids)

            p_asrs.append(asr)
            p_keffs.append(keff)
            p_etas.append(eta_max)

        panel_data[ck] = (np.array(p_asrs), np.array(p_keffs), np.array(p_etas))
        n_zero = np.sum(np.array(p_asrs) == 0)
        print(f"  {ck}: {len(p_asrs)} panels, {n_zero} zero-ASR ({n_zero/max(len(p_asrs),1)*100:.1f}%)")

    # ASR zero rates
    asr_zero_rates = {}
    for ck, (asrs, _, _) in panel_data.items():
        asr_zero_rates[ck] = round(float(np.mean(asrs == 0)), 4) if len(asrs) > 0 else None

    # Run OLS for each epsilon
    print("\nRunning OLS regressions...")
    coefficients_by_epsilon = {}
    for eps in EPSILONS:
        eps_key = f"{eps:.0e}"
        coefficients_by_epsilon[eps_key] = {}
        for ck, (p_asrs, p_keffs, p_etas) in panel_data.items():
            if len(p_asrs) < 10:
                continue
            result = run_ols(p_asrs, p_keffs, p_etas, eps)
            coefficients_by_epsilon[eps_key][ck] = result
            print(f"  ε={eps_key} {ck}: keff_β={result['keff_beta_std']:.4f}, η_β={result['eta_beta_std']:.4f}, R²={result['R2']:.4f}")

    # Max coefficient change relative to 1e-6 baseline
    baseline_key = "1e-06"
    max_keff_change = 0.0
    max_eta_change = 0.0
    for eps_key in coefficients_by_epsilon:
        if eps_key == baseline_key:
            continue
        for ck in coefficients_by_epsilon[eps_key]:
            if ck not in coefficients_by_epsilon.get(baseline_key, {}):
                continue
            base = coefficients_by_epsilon[baseline_key][ck]
            cur = coefficients_by_epsilon[eps_key][ck]
            if abs(base["keff_beta_std"]) > 1e-10:
                chg = abs((cur["keff_beta_std"] - base["keff_beta_std"]) / base["keff_beta_std"]) * 100
                max_keff_change = max(max_keff_change, chg)
            if abs(base["eta_beta_std"]) > 1e-10:
                chg = abs((cur["eta_beta_std"] - base["eta_beta_std"]) / base["eta_beta_std"]) * 100
                max_eta_change = max(max_eta_change, chg)

    output = {
        "K": K,
        "n_panels": len(all_combos),
        "asr_zero_rates": asr_zero_rates,
        "coefficients_by_epsilon": coefficients_by_epsilon,
        "max_coefficient_change": {
            "keff": round(max_keff_change, 2),
            "eta": round(max_eta_change, 2),
        },
    }

    out_path = "/root/cert_manip_resist_eval/artifacts/results/plan001/epsilon_sensitivity_k5.json"
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    with open(out_path, "w") as f:
        json.dump(output, f, indent=2)
    print(f"\nSaved to {out_path}")
    print(json.dumps(output, indent=2))


